/**
 * Governance-layer protocol objects and helpers.
 *
 * This module is protocol-facing. It defines:
 * - governance object shapes
 * - canonical unsigned payload serialization
 * - signing helpers
 * - verification helpers
 *
 * It does not define runtime storage, vault behavior, or SDK ergonomics.
 */
export type GovernanceProtocolVersion = 'v1.0';
export interface GovernanceIdentityRef {
    agent_id: string;
    public_key: string;
    key_version: number;
}
export interface AuthorityIdentity {
    cbio_protocol: GovernanceProtocolVersion;
    kind: 'authority_identity';
    authority: GovernanceIdentityRef;
}
export interface IssuedAgentIdentity {
    cbio_protocol: GovernanceProtocolVersion;
    kind: 'issued_agent_identity';
    agent: GovernanceIdentityRef;
    authority: GovernanceIdentityRef;
    issuance: {
        issued_at: string;
        expires_at?: string;
        sequence: number;
    };
    capabilities?: string[];
    metadata?: Record<string, string>;
    authority_signature: string;
}
export interface DelegationCertificate {
    cbio_protocol: GovernanceProtocolVersion;
    kind: 'delegation_certificate';
    issuer: GovernanceIdentityRef;
    delegate: GovernanceIdentityRef;
    delegation: {
        issued_at: string;
        expires_at?: string;
        capabilities: string[];
        constraints?: Record<string, string>;
        sequence: number;
    };
    issuer_signature: string;
}
export interface RevocationRecord {
    cbio_protocol: GovernanceProtocolVersion;
    kind: 'revocation_record';
    issuer: GovernanceIdentityRef;
    target: {
        kind: 'issued_agent_identity' | 'delegation_certificate';
        subject_agent_id: string;
        sequence: number;
    };
    revocation: {
        revoked_at: string;
        reason?: string;
    };
    issuer_signature: string;
}
export interface AuthorityChain {
    cbio_protocol: GovernanceProtocolVersion;
    kind: 'authority_chain';
    authority_root: AuthorityIdentity;
    issued_agent: IssuedAgentIdentity;
    delegations?: DelegationCertificate[];
    revocations?: RevocationRecord[];
}
export type GovernanceObject = AuthorityIdentity | IssuedAgentIdentity | DelegationCertificate | RevocationRecord | AuthorityChain;
export type UnsignedIssuedAgentIdentity = Omit<IssuedAgentIdentity, 'authority_signature'>;
export type UnsignedDelegationCertificate = Omit<DelegationCertificate, 'issuer_signature'>;
export type UnsignedRevocationRecord = Omit<RevocationRecord, 'issuer_signature'>;
export type SignableGovernanceObject = UnsignedIssuedAgentIdentity | UnsignedDelegationCertificate | UnsignedRevocationRecord;
export declare function createIdentityRef(publicKey: string, keyVersion?: number): GovernanceIdentityRef;
export declare function createAuthorityIdentity(authority: GovernanceIdentityRef): AuthorityIdentity;
export declare function canonicalizeGovernanceObjectForSigning(object: SignableGovernanceObject): string;
export declare function signIssuedAgentIdentity(authorityPrivateKey: string, object: UnsignedIssuedAgentIdentity): IssuedAgentIdentity;
export declare function signDelegationCertificate(issuerPrivateKey: string, object: UnsignedDelegationCertificate): DelegationCertificate;
export declare function signRevocationRecord(issuerPrivateKey: string, object: UnsignedRevocationRecord): RevocationRecord;
export declare function verifyGovernanceIdentityRef(identity: GovernanceIdentityRef): boolean;
export declare function verifyAuthorityIdentity(identity: AuthorityIdentity): boolean;
export declare function verifyIssuedAgentIdentity(object: IssuedAgentIdentity, now?: number): boolean;
export declare function verifyDelegationCertificate(object: DelegationCertificate, now?: number): boolean;
export declare function verifyRevocationRecord(object: RevocationRecord): boolean;
export declare function verifyAuthorityChain(chain: AuthorityChain, now?: number): boolean;
